    foreach ($data as $item) {
      $animal = Animal::where('breed', $item['animal_breed'])->first();

      if (!$animal) {
        $this->command->warn("Животное с породой '{$item['animal_breed']}' не найдено. Пропускаем...");
        continue;
      }

      $cleanData = $item;
      $cleanData['animal_breed'] = $animal->id;

      AnimalDetail::updateOrCreate(
        ['animal_breed' => $cleanData['animal_breed']],
        $cleanData
      );
    }
  }
